public class LCS {
    public int lcsLength(String s1, String s2) {
        int m=s1.length(), n=s2.length();
        int[][] dp = new int[m+1][n+1];
        for (int i=1; i<=m; i++)
            for (int j=1; j<=n; j++)
                dp[i][j] = s1.charAt(i-1)==s2.charAt(j-1)
                    ? dp[i-1][j-1] + 1
                    : Math.max(dp[i-1][j], dp[i][j-1]);
        return dp[m][n];
    }
    String lcs(String s1, String s2) {
        int m=s1.length(), n=s2.length();
        int[][] dp=new int[m+1][n+1];
        for(int i=1;i<=m;i++) for(int j=1;j<=n;j++) dp[i][j]=s1.charAt(i-1)==s2.charAt(j-1)?dp[i-1][j-1]+1:Math.max(dp[i-1][j],dp[i][j-1]);
        StringBuilder sb=new StringBuilder();int i=m,j=n;
        while(i>0&&j>0){if(s1.charAt(i-1)==s2.charAt(j-1)){sb.insert(0,s1.charAt(i-1));i--;j--;}else if(dp[i-1][j]>dp[i][j-1])i--;else j--;}
        return sb.toString();
    }
    public static void main(String[] args) { System.out.println(new LCS().lcs("ABCBDAB","BDCAB")); }
}

